import { createBuiltinExtensions } from "../extensions/builtin-extensions.js";
import { createDeferredResolvedExtension } from "../extensions/deferred-extension.js";
import { importFirstPartyExtensionModule } from "../extensions/first-party-import.js";
import { getEnvSource } from "../utils/env-loader.js";
import { getHostEnv } from "../platform/compat/process/env.js";
/** Select process-owned extensions before server bootstrap orchestration. */
export function createServerBuiltinExtensions(readHostEnv = getHostEnv, readEnvSource = getEnvSource) {
    const extensions = createBuiltinExtensions();
    // Hosted workflows borrow the process-owned Redis runtime. Project config
    // cannot activate extensions on this shared server; local projects opt in.
    const localCliProxyMode = readHostEnv("VERYFRONT_CLI_LOCAL_PROXY_MODE") === "1" &&
        readEnvSource("VERYFRONT_CLI_LOCAL_PROXY_MODE").source === "process";
    if (readHostEnv("PROXY_MODE") === "1" && !localCliProxyMode && readHostEnv("REDIS_URL")) {
        extensions.push(createDeferredResolvedExtension({
            name: "ext-redis",
            source: "builtin",
            origin: "hosted server Redis runtime",
            load: async () => {
                const module = await importFirstPartyExtensionModule("ext-redis", "@veryfront/ext-redis");
                return module.default();
            },
        }));
    }
    return extensions;
}
